                if p in points and p not in comp:
                    comp.add(p); stack.append(p)
    r0=min(r for r,c in comp); c0=min(c for r,c in comp)
    shape={(r-r0,c-c0) for r,c in comp}
    sh, sw=max(r for r,c in shape)+1, max(c for r,c in shape)+1
    out=[row[:] for row in grid]
    for r in range(h-sh+1):
